# =====================================================================================
# v=515 (Hadamard order 2060), c=6 architecture, G = Z2 x Z3 x Z85, multiplier u=161, compression 13:
# EXACT two-sided lift of the 36 yc classes.  Paste this WHOLE file into ONE notebook cell and run.
#
# What it does, per class: enumerate ALL +-1 lifts of each block matching both compressions (z mod 17 from stage A,
# z mod 5 = the class), PSD-filter, exact 4-list join (batched).  A hit is assembled with 347's corner/border into the
# full 2060 x 2060 matrix and checked H H^T = 2060 I.  A class with 0 solutions is an exact null.
#
# EDIT ONLY THESE (just below the imports):
#   INSTANCE, NINST : run NINST notebooks in parallel with INSTANCE = 0, 1, ..., NINST-1 (same NINST in all).
#                     Instance i takes classes c with c % NINST == i.  0 <= INSTANCE < NINST is checked BEFORE any work.
#   CLASS_LIST      : optional explicit list, e.g. [0, 5, 9]; overrides INSTANCE/NINST.
#   RESUME_FROM     : None, or the path of a previous run's output folder added as an input dataset
#                     (e.g. '/kaggle/input/<dataset>/lift515'); classes already logged there are skipped.
#   SELFTEST        : True runs a 1-minute check on the known v=347 matrix first (must print SELFTEST PASS).
# Expect roughly 3-6 hours per class on 4 cores [estimate]; the run stops starting new classes after MAX_HOURS.
# OUTPUT (small): /kaggle/working/lift515/log_inst<I>.jsonl (one line per finished class) and, if any,
#   solutions_*.txt.  Every class result and every SOLUTION is also printed in the cell output.
# =====================================================================================
import os, sys, json, time, base64, io, warnings, numpy as np
warnings.filterwarnings('ignore', category=RuntimeWarning)   # uint64 hash wraparound is intentional

INSTANCE = 0          # <<< EDIT: 0 .. NINST-1
NINST = 4             # <<< EDIT: number of parallel notebooks (same value in all of them)
CLASS_LIST = None     # <<< optional, e.g. [0, 7, 13]
RESUME_FROM = None    # <<< optional previous output folder
SELFTEST = True
MAX_HOURS = 11.0      # do not START a class after this many hours (Kaggle limit is 12 h)
JOIN_BATCH = 1e9      # stored pairs per batch in the exact join (~16 GB at 1e9; lower if memory is short)

WORK = os.environ.get('LIFT515_WORK','/kaggle/working/lift515_code'); OUT = os.environ.get('LIFT515_OUT','/kaggle/working/lift515_c13')
MODULES = {"scripts/bge3_lift.py": "\"\"\"Compression-and-lift solver for the c=6 (b=5) architecture of v=347:  v = 6(h+1)-1, G = Z2 x Z3 x Z_h,\nH = {(0,0,z)}, target sum_k PAF_k = -4b on H\\\\{0}, +4 off H.  h = p*t, K = subgroup of Z_h of order p.\nStage A: compressed sequences on Gc = Z2 x Z3 x Z_t (entries in {-p..p}, parity p), constant on orbits of the\n         symmetry S (scalar multiplier u), Q-coset sums fixed to 347's pattern + shift; compressed PAF target\n         Tc(g') = sum over the K-coset of T (norm at g'=0: 4m - 4b(p-1)).  Annealing with +-2 transfers\n         between orbits of equal Q-coset footprint.\nStage B: lift to +-1 on G, constant on S-orbits, K-fibre sums equal to the stage-A solution; annealing with\n         opposite-sign orbit swaps of equal fibre footprint.  Full energy.\nOn success: assemble with 347's corner/border (data/template347.npz), verify H H^T = 4v I.\nusage: bge3_lift.py h p u [seed] [max_seconds]     env ITERS_A, ITERS_B, LIFT_TRIES\"\"\"\nimport sys, os, json, time, numpy as np, numba as nb\nfrom math import gcd\nh=int(sys.argv[1]); p=int(sys.argv[2]); u=int(sys.argv[3]); seed=int(sys.argv[4]) if len(sys.argv)>4 else 0\ntmax=float(sys.argv[5]) if len(sys.argv)>5 else 600\nassert h%p==0; t=h//p; b=5; c=6; v=c*(h+1)-1; m=c*h; mc=c*t; N=4*v\nITA=int(float(os.environ.get('ITERS_A','2e6'))); ITB=int(float(os.environ.get('ITERS_B','5e6'))); LT=int(os.environ.get('LIFT_TRIES','4'))\nT=np.load('data/template347.npz'); comp=T['comp']; layout=json.loads(str(T['layout']))\nrng=np.random.default_rng(seed)\ndef grp(n):\n    co=np.array([(a,bb,z) for a in range(2) for bb in range(3) for z in range(n)])\n    idx=lambda X: ((np.asarray(X)[...,0]%2)*3+(np.asarray(X)[...,1]%3))*n+(np.asarray(X)[...,2]%n)\n    return co,idx\nco,idx=grp(h); coc,idxc=grp(t)\nADD=idx(co[:,None,:]+co[None,:,:]).astype(np.int32); NEG=idx(-co).astype(np.int32)\nADDc=idxc(coc[:,None,:]+coc[None,:,:]).astype(np.int32); NEGc=idxc(-coc).astype(np.int32)\nQc=(co[:,0]*3+co[:,1]).astype(np.int32); Qcc=(coc[:,0]*3+coc[:,1]).astype(np.int32)\npi=idxc(np.stack([co[:,0],co[:,1],co[:,2]%t],1)).astype(np.int32)          # compression map G -> Gc\nT_full=np.where((co[:,0]==0)&(co[:,1]==0),-4*b,4).astype(np.int64); T_full[0]=4*m\nTc=np.zeros(mc,np.int64); np.add.at(Tc,pi,T_full)\ne=int(np.lcm.reduce([2,3,h])); assert gcd(u,e)==1\ndef orbits(n,co_,idx_,mod):\n    perm=idx_(co_*(u%mod)); lab=-np.ones(len(co_),int); orbs=[]\n    for x in range(len(co_)):\n        if lab[x]<0:\n            o=[]; y=x\n            while lab[y]<0: lab[y]=len(orbs); o.append(y); y=perm[y]\n            orbs.append(o)\n    return lab,orbs\nlab,orbs=orbits(h,co,idx,e); labc,orbsc=orbits(t,coc,idxc,int(np.lcm.reduce([2,3,t])))\nr=len(orbs); rc=len(orbsc)\ndef pack(orbs_):\n    L=max(len(o) for o in orbs_); A=np.full((len(orbs_),L),-1,np.int32)\n    for i,o in enumerate(orbs_): A[i,:len(o)]=o\n    return A\nOM=pack(orbs); OMc=pack(orbsc)\n# footprints: stage A (Q-coset counts per compressed orbit), stage B (fibre counts per full orbit)\nfootA=np.zeros((rc,6),np.int64)\nfor i,o in enumerate(orbsc):\n    for x in o: footA[i,Qcc[x]]+=1\nfkeyA=np.unique(footA,axis=0,return_inverse=True)[1].astype(np.int32)\nfootB=np.zeros((r,mc),np.int64)\nfor i,o in enumerate(orbs):\n    for x in o: footB[i,pi[x]]+=1\nfkeyB=np.unique(footB,axis=0,return_inverse=True)[1].astype(np.int32)\n# shifts (Q-coset sums = comp + even shift, sum a^2 = 4v)\nR_=2*((h+7)//2); a0=comp.sum(1); allowed=[[s for s in range(-R_,R_+1,2) if np.abs(comp[k]+s).max()<=h] for k in range(4)]\nshifts=[]\nfor s0 in allowed[0]:\n    for s1 in allowed[1]:\n        for s2 in allowed[2]:\n            rem=4*v-(a0[0]+6*s0)**2-(a0[1]+6*s1)**2-(a0[2]+6*s2)**2\n            if rem<0: continue\n            rt=int(round(rem**0.5))\n            if rt*rt!=rem: continue\n            for a3 in {rt,-rt}:\n                if (a3-a0[3])%6==0 and (a3-a0[3])//6 in allowed[3]:\n                    s=(s0,s1,s2,(a3-a0[3])//6); shifts.append((s,comp+np.array(s)[:,None]))\n@nb.njit(cache=True)\ndef pafsum(F,ADD):\n    K,n=F.shape; P=np.zeros(n,np.int64)\n    for k in range(K):\n        for g in range(n):\n            s=0\n            for x in range(n): s+=F[k,x]*F[k,ADD[x,g]]\n            P[g]+=s\n    return P\n@nb.njit(cache=True)\ndef anneal_A(Y,F,OM,fkey,ADD,NEG,T,bound,seed,iters,T0,T1):\n    \"\"\"integer orbit values Y (K x rc), F expanded; moves: +2 on o1, -2 on o2 (same footprint), |value|<=bound\"\"\"\n    np.random.seed(seed); K,rc=Y.shape; n=F.shape[1]; P=pafsum(F,ADD)\n    E=0\n    for g in range(n): d=P[g]-T[g]; E+=d*d\n    D=np.zeros(n,np.int64); Temp=T0; best=E\n    for it in range(iters):\n        k=np.random.randint(K); o1=np.random.randint(rc); o2=-1\n        for tries in range(30):\n            q=np.random.randint(rc)\n            if q!=o1 and fkey[q]==fkey[o1]: o2=q; break\n        if o2<0 or Y[k,o1]+2>bound or Y[k,o2]-2<-bound: continue\n        for g in range(n): D[g]=0\n        for (oo,dl) in ((o1,2),(o2,-2)):\n            for j in range(OM.shape[1]):\n                x=OM[oo,j]\n                if x<0: break\n                fx=F[k,x]\n                D[0]+=2*dl*fx+dl*dl\n                for g in range(1,n): D[g]+=dl*(F[k,ADD[x,g]]+F[k,ADD[x,NEG[g]]])\n                F[k,x]=fx+dl\n        e=0\n        for g in range(n): d=P[g]+D[g]-T[g]; e+=d*d\n        if e<=E or np.random.random()<np.exp((E-e)/Temp):\n            Y[k,o1]+=2; Y[k,o2]-=2\n            for g in range(n): P[g]+=D[g]\n            E=e\n            if E<best: best=E\n            if E==0: return 0,best\n        else:\n            for (oo,dl) in ((o2,-2),(o1,2)):\n                for j in range(OM.shape[1]):\n                    x=OM[oo,j]\n                    if x<0: break\n                    F[k,x]-=dl\n        if it%1000==0: Temp=T0*(T1/T0)**(it/iters)\n    return E,best\n@nb.njit(cache=True)\ndef anneal_B(Y,F,OM,fkey,ADD,NEG,T,seed,iters,T0,T1):\n    np.random.seed(seed); K,r=Y.shape; n=F.shape[1]; P=pafsum(F,ADD)\n    E=0\n    for g in range(1,n): d=P[g]-T[g]; E+=d*d\n    D=np.zeros(n,np.int64); Temp=T0; best=E\n    for it in range(iters):\n        k=np.random.randint(K); q1=np.random.randint(r); q2=-1\n        for tries in range(30):\n            qq=np.random.randint(r)\n            if qq!=q1 and fkey[qq]==fkey[q1] and Y[k,qq]==-Y[k,q1]: q2=qq; break\n        if q2<0: continue\n        for g in range(n): D[g]=0\n        for qq in (q1,q2):\n            for j in range(OM.shape[1]):\n                x=OM[qq,j]\n                if x<0: break\n                fx=F[k,x]\n                for g in range(1,n): D[g]+=-2*fx*(F[k,ADD[x,g]]+F[k,ADD[x,NEG[g]]])\n                F[k,x]=-fx\n        e=0\n        for g in range(1,n): d=P[g]+D[g]-T[g]; e+=d*d\n        if e<=E or np.random.random()<np.exp((E-e)/Temp):\n            Y[k,q1]=-Y[k,q1]; Y[k,q2]=-Y[k,q2]\n            for g in range(1,n): P[g]+=D[g]\n            E=e\n            if E<best: best=E\n            if E==0: return 0,best\n        else:\n            for qq in (q2,q1):\n                for j in range(OM.shape[1]):\n                    x=OM[qq,j]\n                    if x<0: break\n                    F[k,x]=-F[k,x]\n        if it%1000==0: Temp=T0*(T1/T0)**(it/iters)\n    return E,best\ndef expand(Y,OM,n):\n    F=np.zeros((Y.shape[0],n),np.int64)\n    for k in range(Y.shape[0]):\n        for i in range(OM.shape[0]):\n            for x in OM[i]:\n                if x<0: break\n                F[k,x]=Y[k,i]\n    return F\ndef init_A(cs):\n    \"\"\"integer orbit values (parity p, |.|<=p) with Q-coset sums cs[k] (random greedy repair)\"\"\"\n    Y=np.empty((4,rc),np.int64)\n    for k in range(4):\n        for attempt in range(500):\n            y=rng.choice(np.arange(-p,p+1,2),size=rc); cur=footA.T@y\n            for it in range(40*rc):\n                diff=cs[k]-cur\n                if not diff.any(): break\n                i=rng.integers(rc); step=2*np.sign(diff@footA[i]) if (diff@footA[i])!=0 else 0\n                if step==0 or abs(y[i]+step)>p: continue\n                new=cur+step*footA[i]\n                if np.abs(cs[k]-new).sum()<np.abs(diff).sum(): y[i]+=step; cur=new\n            if (cur==cs[k]).all(): Y[k]=y; break\n        else: return None\n    return Y\ndef init_B(xc):\n    \"\"\"+-1 orbit signs with fibre sums xc (per Gc element), greedy repair\"\"\"\n    Y=np.empty((4,r),np.int64)\n    for k in range(4):\n        for attempt in range(500):\n            y=rng.choice([-1,1],size=r); cur=footB.T@y\n            for it in range(40*r):\n                diff=xc[k]-cur\n                if not diff.any(): break\n                i=rng.integers(r); dd=diff@footB[i]\n                if dd==0 or np.sign(dd)==y[i]: continue\n                new=cur-2*y[i]*footB[i]\n                if np.abs(xc[k]-new).sum()<np.abs(diff).sum(): y[i]=-y[i]; cur=new\n            if (cur==xc[k]).all(): Y[k]=y; break\n        else: return None\n    return Y\nt0=time.time(); stats=dict(A_runs=0,A_solved=0,lift_runs=0,A_best=None,B_best=None); solved=None; tries=0\nwhile time.time()-t0<tmax and solved is None:\n    s,cs=shifts[tries%len(shifts)]; tries+=1\n    YA=init_A(cs)\n    if YA is None: continue\n    FA=expand(YA,OMc,mc); stats['A_runs']+=1\n    EA,bA=anneal_A(YA,FA,OMc,fkeyA,ADDc,NEGc,Tc,p,seed*7919+tries,ITA,float(4*mc*p),1.0)\n    stats['A_best']=bA if stats['A_best'] is None else min(stats['A_best'],bA)\n    if EA!=0: continue\n    stats['A_solved']+=1\n    for lt in range(LT):\n        YB=init_B(FA)\n        if YB is None: break\n        FB=expand(YB,OM,m); stats['lift_runs']+=1\n        EB,bB=anneal_B(YB,FB,OM,fkeyB,ADD,NEG,T_full,seed*104729+tries*31+lt,ITB,float(2*m),1.0)\n        stats['B_best']=bB if stats['B_best'] is None else min(stats['B_best'],bB)\n        if EB==0:\n            P=pafsum(FB,ADD)\n            if np.array_equal(P[1:],T_full[1:]): solved=FB; break\n    if stats['A_runs']%10==0: print(json.dumps(dict(progress=True,secs=round(time.time()-t0),**stats)),flush=True)\nres=dict(h=h,p=p,t=t,v=v,u=u,r=r,rc=rc,n_shifts=len(shifts),secs=round(time.time()-t0,1),solved=solved is not None,**stats)\nif solved is not None:\n    F=solved; off=20; Hm=np.zeros((N,N),np.int64); Hm[:off,:off]=T['C']\n    for J in range(4):\n        Hm[:off,off+J*m:off+(J+1)*m]=T['K'][:,J*6+Qc]; Hm[off+J*m:off+(J+1)*m,:off]=T['Kc'][:,J*6+Qc].T\n    sig={'h-g':lambda y,x: ADD[x,NEG[y]],'g+h':lambda y,x: ADD[y,x],'-g-h':lambda y,x: NEG[ADD[y,x]],'g-h':lambda y,x: ADD[y,NEG[x]]}\n    Yg,Xg=np.meshgrid(np.arange(m),np.arange(m),indexing='ij')\n    for key,L in layout.items():\n        I_,J_=int(key[0]),int(key[1]); sg=L['rho_sign']*L['gam_sign']\n        Hm[off+I_*m:off+(I_+1)*m,off+J_*m:off+(J_+1)*m]=sg*F[L['k']][sig[L['sigma']](Yg,Xg)]\n    ok=bool(np.array_equal(Hm@Hm.T,N*np.eye(N,dtype=np.int64))); res['hadamard_verified']=ok\n    with open(f'data/lift_c6_v{v}.txt','w') as fo:\n        fo.write(f'v={v} N={N} b={b} m={m} group=2x3x{h} (mixed radix, last index fastest) u={u} p={p} hadamard_verified={ok}\\n')\n        for k,nm in enumerate('ABCD'): fo.write(nm+'='+''.join('+' if x>0 else '-' for x in F[k])+'\\n')\nprint(json.dumps(res),flush=True)\n", "scripts/bge3_stageB_join.py": "\"\"\"Exact stage B (lift) for the c=6 architecture, as a 4-list join.\nGiven a compressed solution xc (level t = h/p) and symmetry u:\n 1. per block: ALL +-1 S-invariant blocks with K-fibre sums xc[k] (connected components of the fibre-orbit graph,\n    brute force per component, Cartesian product), filtered by P(chi) <= 4v on characters nontrivial on H\n 2. PAF at the lag-class reps (orbits of <S,-1>) and PSD at character-class reps for every survivor\n 3. U = (A - T) + C pairs passing the pair PSD bound -> 64-bit linear hash of the PAF vector, sorted\n    V = B + D pairs passing the bound -> look up -hash(V); exact verification of every candidate\nusage (lib): run(h,p,u,xc) ; __main__ validates on the real 347 compression (h=57,p=3,u=11).\"\"\"\nimport sys, os, time, json, numpy as np, numba as nb\nsys.path.insert(0,'scripts')\n\ndef setup(h,p,u):\n    src=open('scripts/bge3_lift.py').read(); cut=src.index(\"t0=time.time(); stats=dict(\")\n    g={}; sys_argv=sys.argv; sys.argv=['bge3_lift.py',str(h),str(p),str(u),'0','1']\n    exec(src[:cut].replace('cache=True','cache=False'),g); sys.argv=sys_argv\n    return g\n\ndef components(A):\n    \"\"\"A (fibres x orbits) footprint: connected components over orbits (orbits linked by sharing a fibre).\"\"\"\n    nf,no=A.shape; par=list(range(no))\n    def f(x):\n        while par[x]!=x: par[x]=par[par[x]]; x=par[x]\n        return x\n    for fi in range(nf):\n        qs=np.nonzero(A[fi])[0]\n        for q in qs[1:]:\n            a,b=f(qs[0]),f(q)\n            if a!=b: par[a]=b\n    comp={}\n    for q in range(no): comp.setdefault(f(q),[]).append(q)\n    return list(comp.values())\n\ndef enum_lifts(A,target):\n    comps=components(A); parts=[]\n    for cq in comps:\n        fis=np.nonzero(A[:,cq].sum(1))[0]; sub=A[np.ix_(fis,cq)]\n        n=len(cq); assert n<=24, 'component too large'\n        Y=((np.arange(1<<n)[:,None]>>np.arange(n)[None,:])&1)*2-1\n        ok=(Y@sub.T==target[fis][None,:]).all(1)\n        parts.append((cq,Y[ok].astype(np.int8)))\n        if not ok.any(): return np.zeros((0,A.shape[1]),np.int8)\n    total=int(np.prod([len(Y) for _,Y in parts]))\n    out=np.empty((total,A.shape[1]),np.int8); rep=total\n    tile=1\n    for cq,Y in parts:\n        rep//=len(Y)\n        blockv=np.repeat(Y,rep,axis=0)                    # each option repeated rep times\n        out[:,cq]=np.tile(blockv,(tile,1)); tile*=len(Y)\n    return out\n\n@nb.njit(parallel=True,cache=True)\ndef pair_filter_count(PA,PB,bound):\n    n=PA.shape[0]; cnt=np.zeros(n,np.int64)\n    for i in nb.prange(n):\n        c=0\n        for j in range(PB.shape[0]):\n            ok=True\n            for f in range(PA.shape[1]):\n                if PA[i,f]+PB[j,f]>bound: ok=False; break\n            if ok: c+=1\n        cnt[i]=c\n    return cnt\n\n@nb.njit(parallel=True,cache=True)\ndef pair_emit(PA,PB,HA,HB,bound,off,K,I,J):\n    n=PA.shape[0]\n    for i in nb.prange(n):\n        c=off[i]\n        for j in range(PB.shape[0]):\n            ok=True\n            for f in range(PA.shape[1]):\n                if PA[i,f]+PB[j,f]>bound: ok=False; break\n            if ok: K[c]=HA[i]+HB[j]; I[c]=i; J[c]=j; c+=1\n    return 0\n\n@nb.njit(parallel=True,cache=True)\ndef probe(PA,PB,HA,HB,bound,Ks,nch):\n    \"\"\"count/emit V pairs (i,j) with -(HA[i]+HB[j]) in sorted Ks\"\"\"\n    n=PA.shape[0]; hits=np.zeros(n,np.int64)\n    for i in nb.prange(n):\n        c=0\n        for j in range(PB.shape[0]):\n            ok=True\n            for f in range(PA.shape[1]):\n                if PA[i,f]+PB[j,f]>bound: ok=False; break\n            if ok:\n                key=np.uint64(0)-(HA[i]+HB[j]); p=np.searchsorted(Ks,key)\n                if p<Ks.shape[0] and Ks[p]==key: c+=1\n        hits[i]=c\n    return hits\n\ndef run(h,p,u,xc,log=print,maxpairs=3e8,lifts=None):\n    \"\"\"lifts: optional list of 4 pre-enumerated lift arrays (orbit signs), e.g. from the two-sided enumerator\"\"\"\n    g=setup(h,p,u); co=g['co']; m=g['m']; v=g['v']; lab=g['lab']; orbs=g['orbs']; ADD=g['ADD']; T_full=g['T_full']\n    A=g['footB'].T; t0=time.time()\n    # lag classes (orbits of <S,-1> on G\\0) and character classes\n    e=int(np.lcm.reduce([2,3,h])); perm=g['idx'](co*(u%e)); neg=g['NEG']\n    cl=-np.ones(m,int); reps=[]\n    for x in range(1,m):\n        if cl[x]<0:\n            S=set(); y=x\n            while y not in S: S.add(y); S.add(int(neg[y])); y=int(perm[y])\n            for z in S: cl[z]=len(reps)\n            reps.append(x)\n    reps=np.array(reps); L=len(reps)\n    mods=np.array([2,3,h]); chars=co[co[:,2]!=0]\n    # character classes: same orbit structure (multiplication by u, negation) on the dual\n    cperm=g['idx'](chars*(u%e)); ccl={}; creps=[]\n    for ch in chars:\n        key=g['idx'](ch)\n        if key in ccl: continue\n        S=set(); y=int(key)\n        while y not in S: S.add(y); S.add(int(neg[y])); y=int(perm[y])\n        for z in S: ccl[z]=len(creps)\n        creps.append(int(key))\n    creps=np.array(creps)\n    ph=np.exp(2j*np.pi*((co[:,None,:]*co[creps][None,:,:])/mods).sum(-1))\n    lists=[]\n    for k in range(4):\n        Y=enum_lifts(A,xc[k]) if lifts is None else lifts[k]\n        ok=np.zeros(len(Y),bool); PSl=[]                  # chunked PSD filter (memory: never expand the whole list)\n        for s in range(0,len(Y),50000):\n            P_=(np.abs(Y[s:s+50000][:,lab].astype(np.float32)@ph)**2).astype(np.float32); o_=(P_<=4*v+1e-3).all(1)\n            ok[s:s+50000]=o_; PSl.append(P_[o_])\n        Y=Y[ok]; PS=np.concatenate(PSl) if PSl else np.zeros((0,len(creps)),np.float32)\n        PAF=np.empty((len(Y),L),np.int64)\n        for s in range(0,len(Y),20000):\n            Fs=np.fft.fftn(Y[s:s+20000][:,lab].reshape(-1,2,3,h).astype(float),axes=(1,2,3))\n            R=np.rint(np.fft.ifftn(np.abs(Fs)**2,axes=(1,2,3)).real).reshape(len(Fs),-1)\n            PAF[s:s+20000]=R[:,reps].astype(np.int64)\n        lists.append(dict(Y=Y,PS=PS,PAF=PAF))\n        log(json.dumps(dict(stage='list',block=k,lifts=int(ok.size),psd_pass=int(ok.sum()),secs=round(time.time()-t0,1))))\n    # linear hash; A carries -T\n    rng=np.random.default_rng(1); W=rng.integers(1,2**63,size=L,dtype=np.uint64)|np.uint64(1)\n    tgt=T_full[reps]\n    H=[((lists[k]['PAF']-(tgt if k==0 else 0)).astype(np.int64).astype(np.uint64)*W).sum(1) for k in range(4)]\n    bound=np.float32(4*v+1e-3)\n    # U = A + C, V = B + D\n    PS=[lists[k]['PS'] for k in range(4)]\n    # store the pairing with the smaller raw product; stream the other one through it\n    if len(PS[1])*len(PS[3]) <= len(PS[0])*len(PS[2]): st,pr=(1,3),(0,2)\n    else: st,pr=(0,2),(1,3)\n    cnt=pair_filter_count(PS[st[0]],PS[st[1]],bound); nU=int(cnt.sum())\n    log(json.dumps(dict(stage='stored_pairs',blocks=st,n=nU,of=int(len(PS[st[0]]))*int(len(PS[st[1]])),secs=round(time.time()-t0,1))))\n    if nU>maxpairs:\n        # exact fallback: batch on the value of the most spread class (bounded memory per batch)\n        PAFs=[lists[k]['PAF'] for k in range(4)]\n        cls0=int(np.argmax([len(np.unique(PAFs[st[1]][:,c])) for c in range(L)]))\n        log(json.dumps(dict(stage='batched_fallback',cls0=cls0,stored_pairs=nU)))\n        sols=[]\n        def vfy(idxs):\n            Fq=np.array([lists[k]['Y'][idxs[k]][lab] for k in range(4)]).astype(np.int64)\n            P=sum(np.array([int(np.dot(Fq[k],Fq[k][ADD[:,gg]])) for gg in range(m)]) for k in range(4))\n            if np.array_equal(P[1:],T_full[1:]): sols.append(Fq); return True\n            return False\n        join_batched(PS,PAFs,H,cls0,bound,vfy,log=log,batch=float(os.environ.get('JOIN_BATCH','1e8')))\n        log(json.dumps(dict(stage='done',solutions=len(sols),secs=round(time.time()-t0,1))))\n        return sols\n    off=np.concatenate([[0],np.cumsum(cnt)[:-1]]).astype(np.int64)\n    K=np.empty(nU,np.uint64); I=np.empty(nU,np.int32); J=np.empty(nU,np.int32)\n    pair_emit(PS[st[0]],PS[st[1]],H[st[0]],H[st[1]],bound,off,K,I,J)\n    o=np.argsort(K); K=K[o]; I=I[o]; J=J[o]\n    hits=probe(PS[pr[0]],PS[pr[1]],H[pr[0]],H[pr[1]],bound,K,64)\n    log(json.dumps(dict(stage='probe',candidates=int(hits.sum()),secs=round(time.time()-t0,1))))\n    sols=[]\n    for i in np.nonzero(hits)[0]:\n        for j in range(len(PS[pr[1]])):\n            if (PS[pr[0]][i]+PS[pr[1]][j]>bound).any(): continue\n            key=np.uint64(0)-(H[pr[0]][i]+H[pr[1]][j]); pz=np.searchsorted(K,key)\n            while pz<len(K) and K[pz]==key:\n                idxs={st[0]:I[pz],st[1]:J[pz],pr[0]:i,pr[1]:j}\n                Fq=np.array([lists[k]['Y'][idxs[k]][lab] for k in range(4)]).astype(np.int64)\n                P=sum(np.array([int(np.dot(Fq[k],Fq[k][ADD[:,gg]])) for gg in range(m)]) for k in range(4))\n                if np.array_equal(P[1:],T_full[1:]): sols.append(Fq)\n                pz+=1\n    log(json.dumps(dict(stage='done',solutions=len(sols),secs=round(time.time()-t0,1))))\n    return sols\n\n\n@nb.njit(parallel=True,cache=True)\ndef _emit_by_value(P0,P1,H0,H1,v0,v1s,o1,bound,taus,sign,cnt,off,K,I,J,write):\n    \"\"\"pairs (i in list0, j in list1 via sorted values v1s/o1) with v0[i]+v1[j] = sign*tau for tau in taus,\n    passing the PSD bound; key = H0+H1.\"\"\"\n    n=P0.shape[0]\n    for i in nb.prange(n):\n        c=0; w=off[i] if write else 0\n        for tt in range(taus.shape[0]):\n            want=sign*taus[tt]-v0[i]\n            lo=np.searchsorted(v1s,want); hi=np.searchsorted(v1s,want,side='right')\n            for pz in range(lo,hi):\n                j=o1[pz]; ok=True\n                for f in range(P0.shape[1]):\n                    if P0[i,f]+P1[j,f]>bound: ok=False; break\n                if ok:\n                    if write:\n                        K[w]=H0[i]+H1[j]; I[w]=i; J[w]=j; w+=1\n                    else: c+=1\n        if not write: cnt[i]=c\n    return 0\n\ndef join_batched(PS,PAF,H,cls0,bound,verify,log=print,batch=1e8):\n    \"\"\"4-list join sum_k PAF_k = 0 (list 0 carries -target), batched on the value of class cls0.\"\"\"\n    V=[np.ascontiguousarray(P[:,cls0]).astype(np.int64) for P in PAF]\n    st,pr=((1,3),(0,2)) if len(PS[1])*len(PS[3])<=len(PS[0])*len(PS[2]) else ((0,2),(1,3))\n    o1=np.argsort(V[st[1]]).astype(np.int64); v1s=V[st[1]][o1]; o3=np.argsort(V[pr[1]]).astype(np.int64); v3s=V[pr[1]][o3]\n    from collections import Counter\n    va,ca=np.unique(V[st[0]],return_counts=True); vb,cb=np.unique(V[st[1]],return_counts=True)\n    hist=Counter()\n    for a,x in zip(va,ca):\n        for b_,y in zip(vb,cb): hist[int(a+b_)]+=int(x)*int(y)\n    pa=np.unique(V[pr[0]]); pb=np.unique(V[pr[1]]); psums=set(int(a+b_) for a in pa for b_ in pb)\n    taus=[tv for tv in sorted(hist) if -tv in psums]\n    batches=[]; cur=[]; load=0\n    for tv in taus:\n        if load+hist[tv]>batch and cur: batches.append(cur); cur=[]; load=0\n        cur.append(tv); load+=hist[tv]\n    if cur: batches.append(cur)\n    found=[]; tot_st=0; tot_c=0\n    z=np.zeros(1,np.int64); zu=np.zeros(1,np.uint64); zi=np.zeros(1,np.int32)\n    for bt in batches:\n        tb=np.array(bt,np.int64)\n        cnt=np.zeros(len(PS[st[0]]),np.int64)\n        _emit_by_value(PS[st[0]],PS[st[1]],H[st[0]],H[st[1]],V[st[0]],v1s,o1,bound,tb,1,cnt,z,zu,zi,zi,False)\n        n=int(cnt.sum()); tot_st+=n\n        if n==0: continue\n        off=np.concatenate([[0],np.cumsum(cnt)[:-1]]).astype(np.int64)\n        K=np.empty(n,np.uint64); I=np.empty(n,np.int32); J=np.empty(n,np.int32)\n        _emit_by_value(PS[st[0]],PS[st[1]],H[st[0]],H[st[1]],V[st[0]],v1s,o1,bound,tb,1,cnt,off,K,I,J,True)\n        o=np.argsort(K); K=K[o]; I=I[o]; J=J[o]\n        cntp=np.zeros(len(PS[pr[0]]),np.int64)\n        _emit_by_value(PS[pr[0]],PS[pr[1]],H[pr[0]],H[pr[1]],V[pr[0]],v3s,o3,bound,tb,-1,cntp,z,zu,zi,zi,False)\n        if int(cntp.sum())==0: continue\n        # probe side in row chunks (bounded memory)\n        cum=np.cumsum(cntp); r0=0\n        while r0<len(cntp):\n            base=cum[r0-1] if r0>0 else 0\n            r1=int(np.searchsorted(cum,base+5e7,side='right')); r1=max(r1,r0+1)\n            sub=np.arange(r0,min(r1,len(cntp)))\n            mm=int(cntp[sub].sum())\n            if mm:\n                subcnt=cntp[sub].copy(); suboff=np.concatenate([[0],np.cumsum(subcnt)[:-1]]).astype(np.int64)\n                Kp=np.empty(mm,np.uint64); Ip=np.empty(mm,np.int32); Jp=np.empty(mm,np.int32)\n                Pm=np.ascontiguousarray(PS[pr[0]][sub]); Hm=np.ascontiguousarray(H[pr[0]][sub]); Vm=np.ascontiguousarray(V[pr[0]][sub])\n                _emit_by_value(Pm,PS[pr[1]],Hm,H[pr[1]],Vm,v3s,o3,bound,tb,-1,subcnt,suboff,Kp,Ip,Jp,True)\n                need=np.uint64(0)-Kp\n                pos=np.searchsorted(K,need); hitm=(pos<len(K))&(K[np.minimum(pos,len(K)-1)]==need)\n                for q in np.nonzero(hitm)[0]:\n                    pz=pos[q]\n                    while pz<len(K) and K[pz]==need[q]:\n                        idx={st[0]:int(I[pz]),st[1]:int(J[pz]),pr[0]:int(sub[Ip[q]]),pr[1]:int(Jp[q])}\n                        tot_c+=1\n                        if verify(idx): found.append(idx)\n                        pz+=1\n            r0=min(r1,len(cntp))\n    log(json.dumps(dict(stage='join_batched',batches=len(batches),stored_pairs=int(tot_st),candidates=int(tot_c),solutions=len(found))))\n    return found\n\nif __name__=='__main__':\n    h,p,u=57,3,11\n    g=setup(h,p,u); T=np.load('data/template347.npz'); Fr=np.array(T['F']).astype(np.int64)\n    xc=np.zeros((4,g['mc']),np.int64)\n    for k in range(4): np.add.at(xc[k],g['pi'],Fr[k])\n    sols=run(h,p,u,xc,log=lambda s: print(s,flush=True))\n    if sols:\n        np.save('data/stageB_347_solutions.npy',np.array(sols))\n        same=[any(np.array_equal(s[k],Fr[k]) for k in range(4)) for s in sols]\n        print(json.dumps(dict(found=len(sols),matches_real_blocks=same)),flush=True)\n", "scripts/bge3_twosided.py": "\"\"\"Two-sided compression-and-lift for c=6 when h = p*q (e.g. 515: h=85=5*17).\nA lift F (+-1 on G = Z2 x Z3 x Z_h, constant on <u>-orbits) has two compressions: xc onto Z_t (t=h/p, from stage A at p)\nand yc onto Z_p (fibres z mod p).  Given xc, the lift splits into independent components (fibre-orbit graph); each\ncomponent's admissible sign patterns contribute a vector to yc.  Step 1 (this file, lib): the exact distribution of yc\nover all lifts of xc (convolution over components), i.e. the lift list is partitioned by yc.\nlib: yc_setup(g,p2) ; yc_distribution(g,comps,xck,Ymap) -> dict yc_tuple -> log2 count\"\"\"\nimport numpy as np, math\n\ndef yc_setup(g,p2):\n    \"\"\"Z_{p2} fibre map of the full group and per-orbit footprint on it (orbit -> counts per yc cell).\"\"\"\n    co=g['co']; h=g['h'] if 'h' in g else int(co[:,2].max())+1\n    cell=((co[:,0]%2)*3+(co[:,1]%3))*p2+(co[:,2]%p2)\n    A=g['footB'].T                                   # (fibres_xc, orbits)\n    no=A.shape[1]; foot=np.zeros((no,6*p2),np.int64)\n    for x in range(len(co)): foot[g['lab'][x],cell[x]]+=1\n    return foot\n\ndef comp_options(A,cq,xck):\n    fis=np.nonzero(A[:,cq].sum(1))[0]; sub=A[np.ix_(fis,cq)]; n=len(cq)\n    Y=((np.arange(1<<n)[:,None]>>np.arange(n)[None,:])&1)*2-1\n    return Y[(Y@sub.T==xck[fis][None,:]).all(1)]\n\ndef yc_distribution(g,comps,xck,foot,maxstates=5_000_000):\n    \"\"\"exact distribution {yc (tuple): count} of the Z_p2 compression over all lifts of xck; None if too many states.\"\"\"\n    A=g['footB'].T; dist={(0,)*foot.shape[1]:1}\n    # process components with the fewest distinct contributions first\n    items=[]\n    for cq in comps:\n        Y=comp_options(A,cq,xck)\n        if len(Y)==0: return {}\n        contrib=Y@foot[cq]; u,c=np.unique(contrib,axis=0,return_counts=True)\n        items.append([(tuple(int(x) for x in r),int(n)) for r,n in zip(u,c)])\n    items.sort(key=len)\n    for it in items:\n        nd={}\n        for k,c in dist.items():\n            for r,n in it:\n                kk=tuple(a+b for a,b in zip(k,r)); nd[kk]=nd.get(kk,0)+c*n\n        dist=nd\n        if len(dist)>maxstates: return None\n    return dist\n\ndef yc_lists(g,comps,xc,p2,S,rng,log=print,chunk=200000):\n    \"\"\"sample S lifts per block, keep PSD-passing, return per block: distinct yc (cells over Z2xZ3xZ_p2) and hit counts.\"\"\"\n    from bge3_residue import lift_sampler\n    co=g['co']; v=g['v']; h=int(co[:,2].max())+1; mods=np.array([2,3,h]); chars=co[co[:,2]!=0]\n    ph=np.exp(2j*np.pi*((co[:,None,:]*chars[None,:,:])/mods).sum(-1))\n    cell=((co[:,0]%2)*3+(co[:,1]%3))*p2+(co[:,2]%p2); out=[]\n    for k in range(4):\n        acc={}\n        for a in range(0,S,chunk):\n            F=lift_sampler(g,comps,xc[k],min(chunk,S-a),rng).astype(float)\n            F=F[((np.abs(F@ph)**2)<=4*v+1e-6).all(1)]\n            if len(F)==0: continue\n            Yc=np.zeros((len(F),6*p2)); np.add.at(Yc.T,cell,F.T); uq,c=np.unique(Yc.astype(np.int64),axis=0,return_counts=True)\n            for r,n in zip(map(tuple,uq.tolist()),c.tolist()): acc[r]=acc.get(r,0)+n\n        Y=np.array(list(acc.keys()),np.int64).reshape(-1,6*p2); N=np.array(list(acc.values()),np.int64)\n        log(dict(stage='yc_list',block=k,distinct=int(len(Y)),hits=int(N.sum()))); out.append((Y,N))\n    return out\n\ndef yc_join(g,ycl,p2,u,log=print,nbuckets=2000,max_solutions=100):\n    \"\"\"4-list join on the Z_p2-compressed PAF: find (yA,yB,yC,yD) from the lists with sum_k PAF(y_k) = T (compressed).\"\"\"\n    import sys; sys.path.insert(0,'scripts'); from kt_generic import kt_join4\n    co=g['co']; cell=((co[:,0]%2)*3+(co[:,1]%3))*p2+(co[:,2]%p2)\n    co2=np.array([(a,b,z) for a in range(2) for b in range(3) for z in range(p2)]); idx2=lambda X:((X[...,0]%2)*3+(X[...,1]%3))*p2+(X[...,2]%p2)\n    T2=np.zeros(6*p2,np.int64); np.add.at(T2,cell,g['T_full'])\n    seen=set(); reps=[]\n    for x in range(6*p2):\n        if x in seen: continue\n        y=x; orb=set()\n        while y not in orb: orb.add(y); orb.add(int(idx2(-co2[y]))); y=int(idx2(co2[y]*u))\n        seen|=orb; reps.append(x)\n    reps=np.array(reps)\n    def paf(Y):\n        F=Y.reshape(-1,2,3,p2).astype(float)\n        return np.rint(np.fft.ifftn(np.abs(np.fft.fftn(F,axes=(1,2,3)))**2,axes=(1,2,3)).real).reshape(len(Y),-1).astype(np.int64)\n    PF=[paf(Y) for Y,_ in ycl]; PAFl=[PF[k][:,reps]-(T2[reps] if k==0 else 0) for k in range(4)]\n    sols=[]\n    def verify(ix):\n        tot=sum(PF[k][ix[k]] for k in range(4))\n        if np.array_equal(tot,T2): sols.append(tuple(int(i) for i in ix)); return True\n        return False\n    kt_join4(PAFl,verify,nbuckets=nbuckets,max_solutions=max_solutions,log=lambda s: log(s) if ('kt_done' in s or 'kt_setup' in s or 'kt_buckets' in s) else None,target_pairs=1e6)\n    return sols\n\ndef _half_product(parts,no):\n    \"\"\"all combinations over a list of (cq, options Y, contribution C): returns (signs (n,no) int8, contrib (n,d) int64).\"\"\"\n    total=int(np.prod([len(Y) for _,Y,_ in parts])) if parts else 1\n    d=parts[0][2].shape[1] if parts else 0\n    S=np.zeros((total,no),np.int8); Cs=np.zeros((total,d),np.int64); rep=total; tile=1\n    for cq,Y,C in parts:\n        rep//=len(Y); idx=np.tile(np.repeat(np.arange(len(Y)),rep),tile); tile*=len(Y)\n        S[:,cq]=Y[idx]; Cs+=C[idx]\n    return S,Cs\n\ndef enum_lifts_yc(g,comps,xck,yck,foot,maxhalf=2**28,maxout=5*10**7):\n    \"\"\"all lifts (orbit signs) of block compression xck whose z-mod-p2 compression equals yck.  Meet in the middle over\n    components: each half is stored only as 64-bit linear hash keys of its yc contribution (mixed-radix index = choice\n    per component); matches are decoded to sign vectors and checked exactly.\"\"\"\n    A=g['footB'].T; no=A.shape[1]; parts=[]\n    rng=np.random.default_rng(7); W=rng.integers(1,2**62,size=foot.shape[1],dtype=np.int64)\n    for cq in comps:\n        Y=comp_options(A,cq,xck)\n        if len(Y)==0: return np.zeros((0,no),np.int8)\n        C=(Y@foot[cq]).astype(np.int64); parts.append((cq,Y.astype(np.int8),C,(C*W).sum(1)))\n    parts.sort(key=lambda t:-len(t[1])); H1=[];H2=[]; l1=l2=0.0\n    for pt in parts:\n        if l1<=l2: H1.append(pt); l1+=np.log2(len(pt[1]))\n        else: H2.append(pt); l2+=np.log2(len(pt[1]))\n    if max(l1,l2)>np.log2(maxhalf): raise MemoryError(f'half too large: 2^{max(l1,l2):.1f}')\n    def keys(H):\n        k=np.zeros(1,np.int64)\n        for _,_,_,kp in H: k=(k[:,None]+kp[None,:]).ravel()          # last part fastest (int64 wraparound is consistent)\n        return k\n    def decode(H,idx):\n        S=np.zeros((len(idx),no),np.int8); idx=idx.copy()\n        for cq,Y,_,_ in reversed(H):\n            d=idx%len(Y); idx//=len(Y); S[:,cq]=Y[d]\n        return S\n    k1=keys(H1); o=np.argsort(k1); k1s=k1[o]; del k1\n    tgt=np.int64((np.asarray(yck,np.int64)*W).sum())\n    k2=keys(H2); need=tgt-k2; del k2\n    lo=np.searchsorted(k1s,need); hi=np.searchsorted(k1s,need,side='right'); cnt=hi-lo; n=int(cnt.sum())\n    if n>maxout: raise MemoryError(f'too many lifts: {n}')\n    j2=np.repeat(np.nonzero(cnt)[0],cnt[cnt>0]); i1=np.concatenate([o[a:b] for a,b in zip(lo[cnt>0],hi[cnt>0])]) if n else np.zeros(0,np.int64)\n    out=decode(H1,i1)+decode(H2,j2) if n else np.zeros((0,no),np.int8)\n    ok=((out.astype(np.int64)@foot)==np.asarray(yck)[None,:]).all(1) if n else np.zeros(0,bool)\n    return out[ok]\n"}
TEMPLATE_B64 = ""
JOB_B64 = ""

def _prepare():
    os.makedirs(os.path.join(WORK,'scripts'),exist_ok=True); os.makedirs(os.path.join(WORK,'data'),exist_ok=True); os.makedirs(OUT,exist_ok=True)
    for p,src in MODULES.items(): open(os.path.join(WORK,p),'w').write(src)
    open(os.path.join(WORK,'data/template347.npz'),'wb').write(base64.b64decode(TEMPLATE_B64))
    os.chdir(WORK); sys.path.insert(0,'scripts'); os.environ['JOIN_BATCH']=str(JOIN_BATCH)

def _assemble(g,F):
    co=g['co']; m=g['m']; v=g['v']; ADD=g['ADD']; NEG=g['NEG']
    Tm=np.load('data/template347.npz'); layout=json.loads(str(Tm['layout'])); N=4*v; off=20
    Qc=(co[:,0]*3+co[:,1]).astype(np.int32); Hm=np.zeros((N,N),np.int64); Hm[:off,:off]=Tm['C']
    for J in range(4):
        Hm[:off,off+J*m:off+(J+1)*m]=Tm['K'][:,J*6+Qc]; Hm[off+J*m:off+(J+1)*m,:off]=Tm['Kc'][:,J*6+Qc].T
    sig={'h-g':lambda y,x: ADD[x,NEG[y]],'g+h':lambda y,x: ADD[y,x],'-g-h':lambda y,x: NEG[ADD[y,x]],'g-h':lambda y,x: ADD[y,NEG[x]]}
    Yg,Xg=np.meshgrid(np.arange(m),np.arange(m),indexing='ij')
    for key,L in layout.items():
        I_,J_=int(key[0]),int(key[1]); sg=L['rho_sign']*L['gam_sign']
        Hm[off+I_*m:off+(I_+1)*m,off+J_*m:off+(J_+1)*m]=sg*F[L['k']][sig[L['sigma']](Yg,Xg)]
    return Hm, bool(np.array_equal(Hm@Hm.T,N*np.eye(N,dtype=np.int64)))

def _selftest():
    from bge3_stageB_join import setup, components, run
    from bge3_twosided import yc_setup, enum_lifts_yc
    g=setup(57,3,11); comps=components(g['footB'].T); foot=yc_setup(g,3); co=g['co']
    Fr=np.array(np.load('data/template347.npz')['F']).astype(np.int64); xc=np.zeros((4,g['mc']),np.int64)
    for k in range(4): np.add.at(xc[k],g['pi'],Fr[k])
    cell=((co[:,0]%2)*3+(co[:,1]%3))*3+(co[:,2]%3); yr=np.zeros((4,18),np.int64)
    for k in range(4): np.add.at(yr[k],cell,Fr[k])
    L=[enum_lifts_yc(g,comps,xc[k],yr[k],foot) for k in range(4)]
    sols=run(57,3,11,xc,log=lambda s: None,lifts=L) or []
    real=any(all(np.array_equal(s[k],Fr[k]) for k in range(4)) for s in sols)
    ok=real and all(_assemble(g,s)[1] for s in sols)
    print(('SELFTEST PASS' if ok else 'SELFTEST FAIL')+f': v=347 lifts {[len(x) for x in L]}, solutions {len(sols)}, real core recovered {real}, all assemble to Hadamard {ok}',flush=True)
    if not ok: raise SystemExit('SELFTEST FAILED - do not trust this environment')

def main():
    t0=time.time(); _prepare()
    J=np.load(io.BytesIO(base64.b64decode(JOB_B64))); xc=J['xc'].astype(np.int64); YC=J['yc'].astype(np.int64); ncl=len(YC)
    if CLASS_LIST is not None: mine=[int(c) for c in CLASS_LIST]
    else:
        if not (isinstance(NINST,int) and NINST>=1 and 0<=INSTANCE<NINST): raise SystemExit(f'ASSIGNMENT CHECK FAILED: need 0 <= INSTANCE < NINST (got INSTANCE={INSTANCE}, NINST={NINST})')
        mine=[c for c in range(ncl) if c%NINST==INSTANCE]
    print(f'ASSIGNMENT CHECK: {len(mine)} of {ncl} classes for this run: {mine}',flush=True)
    if not mine: raise SystemExit('ASSIGNMENT CHECK FAILED: no classes assigned')
    if SELFTEST: _selftest()
    from bge3_stageB_join import setup, components, run
    from bge3_twosided import yc_setup, enum_lifts_yc
    tag=('list' if CLASS_LIST is not None else f'inst{INSTANCE}of{NINST}'); logp=os.path.join(OUT,f'log_{tag}.jsonl')
    done=set()
    for d in [OUT]+([RESUME_FROM] if RESUME_FROM else []):
        if d and os.path.isdir(d):
            for f in os.listdir(d):
                if f.startswith('log_') and f.endswith('.jsonl'):
                    for l in open(os.path.join(d,f)):
                        try: done.add(json.loads(l)['class'])
                        except Exception: pass
    todo=[c for c in mine if c not in done]; print(f'already done (skipped): {sorted(set(mine)&done)}; to run: {todo}',flush=True)
    g=setup(85,5,161); comps=components(g['footB'].T); foot=yc_setup(g,5); cache={}; logf=open(logp,'a')
    for c in todo:
        if time.time()-t0>MAX_HOURS*3600: print('MAX_HOURS reached: not starting further classes',flush=True); break
        tc=time.time(); L=[]
        for k in range(4):
            key=(k,tuple(YC[c,k].tolist()))
            if key not in cache: cache[key]=enum_lifts_yc(g,comps,xc[k],YC[c,k],foot)
            L.append(cache[key])
        print(f'class {c}: lift list sizes {[len(x) for x in L]} (built in {time.time()-tc:.0f} s); exact join running...',flush=True)
        sols=run(85,5,161,xc,log=lambda s: print('   ',s,flush=True) if ('batched' in s or 'stored_pairs' in s) else None,lifts=L) or []
        rec=dict(v=515,u=161,compression=13,**{'class':int(c)},lift_sizes=[int(len(x)) for x in L],solutions=len(sols),hours=round((time.time()-tc)/3600,2))
        logf.write(json.dumps(rec)+'\n'); logf.flush(); print('CLASS RESULT '+json.dumps(rec),flush=True)
        for i,F in enumerate(sols):
            Hm,ok=_assemble(g,F); s=dict(v=515,u=161,compression=13,**{'class':int(c)},hadamard_verified=ok,group='Z2xZ3xZ85 mixed radix, last index fastest',
                  blocks={nm:''.join('+' if x>0 else '-' for x in F[k]) for k,nm in enumerate('ABCD')})
            print('SOLUTION '+json.dumps(s),flush=True)
            open(os.path.join(OUT,f'solution_class{c}_{i}.txt'),'w').write(json.dumps(s)+'\n')
    print(f'RUN SUMMARY: finished {sum(1 for _ in open(logp))} class lines in {logp}; hours {(time.time()-t0)/3600:.2f}',flush=True)

if __name__=='__main__' or 'ipykernel' in sys.modules:
    main()
